func:
let d = msg.payload;
let rssi = Number(d.rssi_dbm);
let calificacion = "";
let recomendadoPara = "";
let alertLevel = "info";

if (rssi >= -60) {
    calificacion = "EXCELENTE";
    recomendadoPara = "Apto para streaming continuo de ECG / EEG de alta velocidad";
    alertLevel = "success";
} else if (rssi >= -75) {
    calificacion = "BUENA";
    recomendadoPara = "Apto para telemetría periódica de SpO2, temperatura y presión arterial";
    alertLevel = "info";
} else if (rssi >= -85) {
    calificacion = "DEFICIENTE";
    recomendadoPara = "Riesgo de retraso en entrega de alarmas; reubicar antena";
    alertLevel = "warn";
} else {
    calificacion = "CRÍTICA";
    recomendadoPara = "INAPTO para monitoreo de pacientes críticos; conexión inestable";
    alertLevel = "danger";
}

msg.payload = {
    red: d.ssid,
    canal: d.channel,
    potencia_dbm: rssi,
    calidad_enlace: calificacion,
    evaluacion_telesalud: recomendadoPara,
    nivel_alerta: alertLevel,
    auditado_en: new Date().toISOString()
};

return msg;
